from __future__ import annotations
import hashlib,json
from pathlib import Path
from finance_query.research.advisory_intent_pre_unseen import validate_pre_unseen
def w(p:Path,v:dict)->str:p.write_text(json.dumps(v)+"\n");return hashlib.sha256(p.read_bytes()).hexdigest()
def test_hash_bound_receipt(tmp_path:Path)->None:
 h=tmp_path/"h.json";d=tmp_path/"d.json";hh=w(h,{"decision_thresholds":{"minimum_newly_correct_development":2,"minimum_precision_on_predictions":1.0,"maximum_false_confident_candidate":0,"maximum_regressed_baseline_predictions":0}});dh=w(d,{"arms":{"B_A_plus_explicit_advisory_abstention":{"precision_on_predictions":1.0,"false_confident_count":0}},"candidate_outcome_counts":{"IMPROVED":3}});r=tmp_path/"r.json";w(r,{"protocol":"explicit_advisory_intent_abstention_pre_unseen_freeze_v1","schema_version":1,"experiment_id":"explicit_advisory_intent_abstention_v1","inputs":{"hypothesis_freeze":{"path":str(h),"sha256":hh},"development_report":{"path":str(d),"sha256":dh}},"development_gate":{"status":"PASS","observed":{"newly_correct":3,"precision_on_predictions":1.0,"false_confident_candidate":0,"regressed_baseline_predictions":0}},"frozen_untouched_predictions":{"minimum_newly_correct_untouched":2,"minimum_precision_on_predictions":1.0,"maximum_false_confident_candidate":0,"maximum_regressed_baseline_predictions":0,"metric_holdout_prediction":{},"composition_holdout_prediction":{}},"untouched_evaluation_allowed":True,"full_vifinqa_dataset_allowed":False,"source_contract":{"research_only":True,"submission_eligible":False,"vifinqa_answer_authority":False}});assert validate_pre_unseen(r,tmp_path)["status"]=="PASS";d.write_text("{}\n");assert validate_pre_unseen(r,tmp_path)["status"]=="FAIL"
